import { execFile } from 'child_process';
import { promisify } from 'util';
import path from 'path';
import { z } from 'zod';
import { GuidanceReferenceNameSchema } from '../types/guidance-references';
import {
  GUIDANCE_SOURCE_BYTES,
  type GuidanceSource,
  type GuidanceSourceContent,
} from '../types/guidance-source';
import { guidanceSourceContent } from './guidanceSourceContent';
import { subprocessEnvironment } from '../utils/subprocessEnvironment';

interface GithubSourceInput {
  source: Extract<GuidanceSource, { kind: 'github' }>;
  signal?: AbortSignal;
  previousRevision?: string;
}

const execute = promisify(execFile);
const REQUEST_TIMEOUT_MS = 30_000;
const RESPONSE_BYTES = 80 * 1024 * 1024;
const RevisionSchema = z.string().regex(/^[a-f0-9]{40,64}$/);
const ReferenceSchema = z.object({
  object: z.object({ type: z.literal('commit'), sha: RevisionSchema }),
});
const TreeSchema = z.object({
  tree: z.array(
    z.object({
      path: z.string(),
      mode: z.string(),
      type: z.string(),
      sha: RevisionSchema,
      size: z.number().optional(),
    }),
  ),
});
const BlobSchema = z.object({
  encoding: z.literal('base64'),
  size: z.number().int().nonnegative().max(GUIDANCE_SOURCE_BYTES),
  content: z.string(),
});

export const readGithubGuidanceSource = async ({
  source,
  signal,
  previousRevision,
}: GithubSourceInput): Promise<GuidanceSourceContent | null> => {
  const repository = new URL(source.repository).pathname
    .replace(/^\//, '')
    .replace(/\/$/, '')
    .replace(/\.git$/, '');
  const request = async (resource: string): Promise<unknown> => {
    const { stdout } = await execute(
      'gh',
      ['api', '--hostname', 'github.com', `repos/${repository}/${resource}`],
      {
        signal,
        timeout: REQUEST_TIMEOUT_MS,
        maxBuffer: RESPONSE_BYTES,
        encoding: 'utf8',
        env: { ...subprocessEnvironment('github'), GH_PROMPT_DISABLED: '1' },
      },
    );
    return JSON.parse(stdout);
  };
  const branch = source.branch.split('/').map(encodeURIComponent).join('/');
  const revision = ReferenceSchema.parse(
    await request(`git/ref/heads/${branch}`),
  ).object.sha;
  if (revision === previousRevision) return null;
  const trees = new Map<string, z.infer<typeof TreeSchema>>();
  return guidanceSourceContent({
    revision,
    read: async (image) => {
      const file = image
        ? path.posix.normalize(
            path.posix.join(path.posix.dirname(source.path), image),
          )
        : source.path;
      const segments = GuidanceReferenceNameSchema.parse(file).split('/');
      let tree = revision;
      for (const [index, segment] of segments.entries()) {
        let listing = trees.get(tree);
        if (!listing) {
          listing = TreeSchema.parse(await request(`git/trees/${tree}`));
          trees.set(tree, listing);
        }
        const entry = listing.tree.find((item) => item.path === segment);
        if (!entry)
          throw new Error('Source file is missing from the selected revision');
        if (index < segments.length - 1) {
          if (entry.type !== 'tree' || entry.mode !== '040000')
            throw new Error('Source directories must be repository trees');
          tree = entry.sha;
          continue;
        }
        if (
          entry.type !== 'blob' ||
          !['100644', '100755'].includes(entry.mode) ||
          (entry.size ?? 0) > GUIDANCE_SOURCE_BYTES
        )
          throw new Error('Source must be a bounded regular repository file');
        const blob = BlobSchema.parse(await request(`git/blobs/${entry.sha}`));
        const content = blob.content.replace(/\s/g, '');
        const bytes = Buffer.from(content, 'base64');
        if (bytes.length !== blob.size || bytes.toString('base64') !== content)
          throw new Error('Source file has invalid content');
        return bytes;
      }
      throw new Error('Source file is missing');
    },
  });
};
